class Solution {
public:
    int makePrefSumNonNegative(vector<int>& nums) {
        priority_queue<int, vector<int>, greater<int>> pq;
        long long sum = 0;
        int operations = 0;
        for (int x : nums) {
            sum += x;
            if (x < 0) pq.push(x);
            if (sum < 0) {
                sum -= pq.top();
                pq.pop();
                ++operations;
            }
        }
        return operations;
    }
};
